from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.E, Direction.CLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
rear_motor = Motor(Port.C, Direction.CLOCKWISE)
left_color_sensor = ColorSensor(Port.B)
right_color_sensor = ColorSensor(Port.F)
WHEEL_DIAMETER = 88
WHEEL_TRACK = 144
PIVOT_RADIUS = WHEEL_TRACK / 2
LEFT_PIVOT = WHEEL_TRACK / -2
RIGHT_PIVOT = WHEEL_TRACK / 2
ADB_GEAR_RATIO = (36 / 28) * (20 / 12)
drive_base = DriveBase(left_wheel, right_wheel, WHEEL_DIAMETER, WHEEL_TRACK)

async def main1():
    drive_base.use_gyro(True)
    await wait(1500)
    await front_motor.run_angle(500, 55)

async def main2():
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=250)
    await drive_base.straight(350, then=Stop.NONE)
    await drive_base.arc(200, angle=25, then=Stop.NONE)
    await drive_base.arc(-200, angle=25, then=Stop.NONE)
    await drive_base.straight(264)
    await drive_base.turn(15)
    front_motor.dc(100)
    await front_motor.run_angle(1000, 270)
    await wait(1000)
    await front_motor.run_angle(500, -330)
    await drive_base.turn(-20)
    await drive_base.straight(-220)
    print('hello world')
    prime_hub.display.char('@')
    await prime_hub.speaker.beep(500, 300)
    raise SystemExit


async def main():
    await multitask(main1(), main2())

run_task(main())